// Regenerates src/bridge/generated: TypeScript types for every JSON payload
// that crosses the Rust core's C ABI (core/crates/core/src/ffi.rs), written
// by ts-rs from the Rust definitions (the `ts` cargo features). Don't edit
// the generated files; change the Rust types and run `npm run bridge:types`.
//
// Steps: clear the folder, run the ts-rs export tests (with the simulator
// feature, so the simulator-only burn requests are typed too), write an
// index.ts re-exporting every type, and format the folder with Prettier.
const { spawnSync } = require('child_process')
const fs = require('fs')
const path = require('path')
const prettier = require('prettier')

const appDir = path.resolve(__dirname, '..')
const coreDir = path.resolve(appDir, '..', 'core')
const bridgeDir = path.join(appDir, 'src', 'bridge', 'generated')

fs.rmSync(bridgeDir, { recursive: true, force: true })
fs.mkdirSync(bridgeDir, { recursive: true })

// Cargo reads core/.cargo/config.toml (TS_RS_EXPORT_DIR, TS_RS_LARGE_INT)
// from the working directory, so run it in core/.
const cargo = spawnSync(
  'cargo',
  [
    'test',
    '--manifest-path',
    path.join(coreDir, 'Cargo.toml'),
    '--workspace',
    '--features',
    'ts,simulator',
    'export_bindings',
  ],
  { cwd: coreDir, stdio: 'inherit' },
)
if (cargo.error) {
  throw cargo.error
}
if (cargo.status !== 0) {
  process.exit(cargo.status ?? 1)
}

/** The generated .ts files under `dir`, as paths relative to bridgeDir. */
const listTypes = dir =>
  fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) {
      return listTypes(full)
    }
    return entry.name.endsWith('.ts') && entry.name !== 'index.ts'
      ? [path.relative(bridgeDir, full).split(path.sep).join('/')]
      : []
  })

const types = listTypes(bridgeDir).toSorted((a, b) => {
  const [x, y] = [path.posix.basename(a), path.posix.basename(b)]
  return x < y ? -1 : x > y ? 1 : 0
})
if (types.length === 0) {
  console.error('ts-rs wrote no types to', bridgeDir)
  process.exit(1)
}

// ts-rs names each file after its type.
const index = [
  '// Generated by app/scripts/gen-bridge-types.js. Do not edit this file manually.',
  ...types.map(file => {
    const name = path.posix.basename(file, '.ts')
    return `export type { ${name} } from './${file.replace(/\.ts$/, '')}'`
  }),
  '',
].join('\n')
fs.writeFileSync(path.join(bridgeDir, 'index.ts'), index)

for (const file of [...types, 'index.ts']) {
  const filepath = path.join(bridgeDir, file)
  const options = prettier.resolveConfig.sync(filepath) ?? {}
  const text = fs.readFileSync(filepath, 'utf8')
  fs.writeFileSync(filepath, prettier.format(text, { ...options, filepath }))
}

console.log(`Wrote ${types.length} bridge types to ${bridgeDir}`)
